function ctResetModal(){styles();document.getElementById('ct_reset_modal')?.remove();const bg=document.createElement('div');bg.id='ct_reset_modal';bg.className='rgbp-modal-bg';const m=document.createElement('div');m.className='rgbp-modal';bg.appendChild(m);const r=ctResetResults(),s=ctResetStats();m.innerHTML=`<h2>Rewind the Battle Report</h2><div>Total ${s.total} | Successful ${s.success} | Failed ${s.failed} | Checked ${s.checked}</div><div style="margin:10px 0" class="controls"><button id="ct_reset_xlsx">Download XLSX</button><button id="ct_reset_clear">Clear Report</button><button id="ct_reset_close">Close</button></div><div style="max-height:58vh;overflow:auto"><table><thead><tr><th>Case ID</th><th>Customer</th><th>Asset</th><th>Serial</th><th>Status</th><th>Result</th><th>Reason</th><th>Time</th></tr></thead><tbody>${r.map(x=>`<tr class="${x.Result==='FAILED'?'f':'c'}"><td>${esc(x['Case ID'])}</td><td>${esc(x.Customer)}</td><td>${esc(x['Asset ID'])}</td><td>${esc(x.Serial)}</td><td>${esc(x.Status)}</td><td><b>${esc(x.Result)}</b></td><td>${esc(x.Reason)}</td><td>${esc(x.Timestamp)}</td></tr>`).join('')}</tbody></table></div>`;document.body.appendChild(bg);m.querySelector('#ct_reset_xlsx').onclick=ctDownloadResetResults;m.querySelector('#ct_reset_clear').onclick=()=>{if(confirm('Clear Rewind the Battle report history?')){ctSetResetResults([]);bg.remove()}};m.querySelector('#ct_reset_close').onclick=()=>bg.remove();bg.onclick=e=>{if(e.target===bg)bg.remove()}}

